<template><main class="paper-shell"><div class="paper-container admin-container"><header class="paper-workspace-header"><div><div class="paper-page-eyebrow">Knowledge Base / Administration</div><h1 class="paper-page-title">Workflow settings</h1><p class="paper-page-description">Configure collection, PDF retrieval, parsing, LLM extraction, and embeddings without exposing stored credentials.</p></div></header><LiteratureAdminNav/><p v-if="message" class="admin-notice" :class="{error}">{{message}}</p><section v-if="loading" class="paper-panel empty">Loading settings…</section><form v-else @submit.prevent="save">
  <section v-for="group in groups" :key="group.title" class="paper-panel admin-card"><h2>{{group.title}}</h2><p>{{group.description}}</p><div class="admin-form"><label v-for="field in group.fields" :key="field.key">{{field.label}}<input v-if="field.type!=='select'" v-model="form[field.key]" :type="field.type||'text'" :step="field.step" :placeholder="field.secret&&configured(field.key)?'Configured — leave blank to keep current value':''"/><select v-else v-model="form[field.key]"><option v-for="option in field.options" :key="option" :value="option">{{option}}</option></select><small v-if="field.secret">{{configured(field.key)?'Credential is configured.':'Credential is not configured.'}}</small></label></div></section><button class="admin-action" :disabled="saving">{{saving?'Saving…':'Save workflow settings'}}</button>
</form></div></main></template>
<script setup>
import '~/assets/paper-platform.css';import {authState,loadCurrentUser} from '~/utils/auth';definePageMeta({middleware:'auth-client'});useHead({title:'Literature Settings - OpenIsle'})
const api=useLiteratureAdmin(),form=reactive({}),original=ref({}),loading=ref(true),saving=ref(false),message=ref(''),error=ref(false)
const groups=[{title:'Collection sources',description:'Default providers used for online metadata collection.',fields:[{key:'collect_sources',label:'Sources (comma separated)'}]},{title:'PDF retrieval priority',description:'Lower values run first; use 0 to disable a strategy.',fields:[{key:'pdf_strategy_crossref_text_mining',label:'Crossref text mining',type:'number'},{key:'pdf_strategy_crossref_pdf',label:'Crossref PDF',type:'number'},{key:'pdf_strategy_oa_url',label:'Open-access URL',type:'number'},{key:'pdf_strategy_doi_redirect',label:'DOI redirect',type:'number'},{key:'pdf_strategy_unpaywall',label:'Unpaywall',type:'number'}]},{title:'PDF parser priority',description:'Configure fallback order for the available parsing engines.',fields:[{key:'pdf_parser_mineru_api',label:'MinerU API',type:'number'},{key:'pdf_parser_pymupdf',label:'PyMuPDF',type:'number'},{key:'pdf_parser_marker_gpu',label:'Marker GPU',type:'number'},{key:'pdf_parser_marker_cpu',label:'Marker CPU',type:'number'},{key:'mineru_api_key',label:'MinerU API key',type:'password',secret:true}]},{title:'LLM extraction',description:'OpenAI-compatible endpoint used for knowledge extraction.',fields:[{key:'llm_base_url',label:'Base URL'},{key:'llm_model',label:'Model'},{key:'llm_max_tokens',label:'Maximum tokens',type:'number'},{key:'llm_temperature',label:'Temperature',type:'number',step:'0.1'},{key:'llm_request_timeout',label:'Timeout seconds',type:'number'},{key:'llm_max_retries',label:'Maximum retries',type:'number'},{key:'llm_api_key',label:'API key',type:'password',secret:true}]},{title:'Semantic search',description:'Embedding endpoint and vector dimensions.',fields:[{key:'embedding_base_url',label:'Base URL'},{key:'embedding_model',label:'Model'},{key:'embedding_dim',label:'Dimensions',type:'number'},{key:'embedding_batch_size',label:'Batch size',type:'number'},{key:'embedding_api_key',label:'API key',type:'password',secret:true}]},{title:'Provider credentials',description:'Optional credentials for higher limits or licensed metadata sources.',fields:[{key:'semantic_scholar_api_key',label:'Semantic Scholar API key',type:'password',secret:true},{key:'wos_api_key',label:'Web of Science API key',type:'password',secret:true},{key:'scopus_api_keys',label:'Scopus API keys',type:'password',secret:true}]}]
const secretKeys=new Set(groups.flatMap(g=>g.fields.filter(f=>f.secret).map(f=>f.key)));const configured=key=>Boolean(original.value[`${key}_configured`]||original.value[key]);const load=async()=>{try{if(!authState.role)await loadCurrentUser();if(authState.role!=='ADMIN')return navigateTo('/literature/workflow');const data=await api.get('/workflow/settings');original.value=data;Object.entries(data).forEach(([k,v])=>{if(!secretKeys.has(k))form[k]=Array.isArray(v)?v.join(', '):v});secretKeys.forEach(k=>form[k]='')}catch(e){error.value=true;message.value=e?.data?.message||e.message}finally{loading.value=false}};const save=async()=>{saving.value=true;message.value='';error.value=false;try{const body={};groups.flatMap(g=>g.fields).forEach(field=>{let value=form[field.key];if(field.secret&&!value)return;if(field.key==='collect_sources')value=String(value||'').split(',').map(x=>x.trim()).filter(Boolean);body[field.key]=value});await api.post('/workflow/settings',body);message.value='Workflow settings saved.';await load()}catch(e){error.value=true;message.value=e?.data?.message||e.message}finally{saving.value=false}};onMounted(load)
</script><style scoped src="~/assets/literature-admin.css"></style><style scoped>small{color:var(--paper-soft);font-weight:400}.admin-action{margin-bottom:30px}</style>
